    99→    const isPrivateIpv4Host = (hostname: string) => {
   100→        const parts = hostname.split('.');
   101→        if (parts.length !== 4) return false;
   102→        const nums = parts.map((p) => parseInt(p, 10));
   103→        if (nums.some((n) => !Number.isFinite(n) || n < 0 || n > 255)) return false;
   104→        const [a, b] = nums;
   105→        if (a === 10) return true;
   106→        if (a === 192 && b === 168) return true;
   107→        if (a === 172 && b >= 16 && b <= 31) return true;
   108→        if (a === 100 && b >= 64 && b <= 127) return true; // CGNAT
   109→        if (a === 169 && b === 254) return true; // link-local
   110→        return false;
   111→    };
