   113→    const isLocalNetworkHost = (hostname: string) => {
   114→        const lower = hostname.toLowerCase();
   115→        if (isLoopbackHost(lower)) return true;
   116→        if (isPrivateIpv4Host(lower)) return true;
   117→        if (lower.startsWith('fd') || lower.startsWith('fc') || lower.startsWith('fe80:')) return true; // IPv6 ULA/link-local
